    defaults = METHOD_DEFAULTS[method]
    _check_keys(table, defaults.keys(), where)
    return {key: _setting(value, defaults[key], f"{where}.{key}") for key, value in table.items()}


def _setting(value: object, default: SettingValue, where: str) -> SettingValue:
    if isinstance(default, bool) or isinstance(value, bool):
        return _typed(value, bool, where)
    if isinstance(default, int):
        return _typed(value, int, where)
    if isinstance(default, float):
        return float(_typed(value, int | float, where))
    return _typed(value, str, where)


def _typed[T](value: object, kind: type[T] | object, where: str) -> T:
    if not isinstance(value, kind):  # type: ignore[arg-type]
        raise TypeError(f"{where} has the wrong type: {value!r}")
    return value

